/// The lucide `<svg>` for `name`, decorative (`aria-hidden`). `None` when the
/// glyph is not vendored; callers then render nothing rather than a broken box.
pub fn svg(name: &str) -> Option<String> {
    let name = name.trim().to_ascii_lowercase();
    let inner = GLYPHS.iter().find(|(id, _)| *id == name)?.1;
    Some(format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" data-icon=\"{name}\">{inner}</svg>"
    ))
}

/// [`svg`] or an empty string.
pub fn svg_or_empty(name: &str) -> String {
    svg(name).unwrap_or_default()
}

pub fn has(name: &str) -> bool {
    let name = name.trim().to_ascii_lowercase();
    GLYPHS.iter().any(|(id, _)| *id == name)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_glyph_is_lucide_svg() {
        let s = svg("download").unwrap();
        assert!(s.starts_with("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\""));
        assert!(s.contains("stroke=\"currentColor\""));
        assert!(s.contains("aria-hidden=\"true\""));
        assert!(s.contains("data-icon=\"download\""));
        assert!(!s.contains("<script"));
    }

    #[test]
    fn unknown_glyph_is_none() {
        assert!(svg("not-an-icon").is_none());
        assert_eq!(svg_or_empty("<b>"), "");
        assert!(has("Heart"));
    }

    #[test]
    fn glyph_table_is_sorted_and_unique() {
        for w in GLYPHS.windows(2) {
            assert!(w[0].0 < w[1].0, "{} before {}", w[0].0, w[1].0);
        }
    }
}
